  const action =
    registry.get(
      event.data?.actionId
    );


  entries.push({
    type:

,

          timestamp:
            event.timestamp
        });
      }
    }


    for (
      const usedAction
      of state.usedActions ??
        []
    ) {
      const action =
        registry.get(
          usedAction.actionId
        );


      if (
        !action
      ) {
        continue;
      }


      entries.push({
        type:
          action.category,

        icon:
          action.icon ||

              : action.cost,

      timestamp:
        usedAction.timestamp
    });
  }


  return (
    entries.sort(
      (
        left,
        right
      ) => {
        return (
          left.timestamp -
          right.timestamp
        );
      }
    )
  );
}

renderCommittedPlan(
  state
) {
  const entries =
    this.committedPlanEntries(
      state
    );


  const entryMarkup =
    entries.length
      ? entries
          .map(
            (
              entry,
              index
            ) => {
              return 
                <li class="frame-helm-plan-entry frame-helm-plan-${foundry.utils.escapeHTML(entry.type)}">
                  <span class="frame-helm-plan-index">
                    ${String(index + 1).padStart(2, "0")}
                  </span>

                  <i class="${foundry.utils.escapeHTML(entry.icon)}"></i>

                  <span class="frame-helm-plan-copy">
                    <strong>
                      ${foundry.utils.escapeHTML(entry.label)}
                    </strong>

                    <small>
                      ${foundry.utils.escapeHTML(entry.detail)}
                    </small>
                  </span>
                </li>
              ;
            }
          )
          .join(

}
